&lt;style&gt;

    


/* Prevent the product form and gallery from expanding beyond their parent */
.layout,
.layout &gt; main,
#productForm,
#productForm .product-step,
#productForm .field {
    min-width: 0;
    max-width: 100%;
    box-sizing: border-box;
}

#productForm .product-step {
    overflow: visible;
}

#imagePreview {
    justify-content: start;
}


/* Product image gallery */
#imagePreview {
    display: grid !important;
    grid-template-columns: repeat(5, minmax(0, 172px));
    gap: 24px 16px;
    align-items: start;
    justify-content: start;
    width: 100%;
    max-width: 100%;
    margin-top: 16px;
    overflow: visible;
    box-sizing: border-box;
}

/* Each image card */
#imagePreview &gt; .image-item,
#imagePreview &gt; .image-add-tile {
    position: relative;
    width: 100%;
    min-width: 0;
    max-width: 172px;
    margin: 0;
    box-sizing: border-box;
}

#imagePreview &gt; .image-item {
    display: flex;
    flex-direction: column;
    align-items: stretch;
}

/* Image thumbnail */
#imagePreview &gt; .image-item &gt; img {
    display: block;
    width: 100%;
    height: 172px;
    padding: 8px;
    object-fit: contain;
    border: 1px solid #dee2e6;
    border-radius: 12px;
    background: #fff;
    box-sizing: border-box;
}

/* Remove button */
#imagePreview .remove-image {
    position: absolute;
    top: -9px;
    right: -9px;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: #e93343;
    color: #fff;
    font-size: 22px;
    line-height: 1;
    cursor: pointer;
}

/* Primary image selection */
#imagePreview .primary-image-option {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 7px;
    width: 100%;
    margin-top: 10px;
    text-align: center;
}

#imagePreview .primary-image-option input[type=&quot;radio&quot;] {
    width: 18px;
    height: 18px;
    margin: 0;
    cursor: pointer;
}

#imagePreview .primary-image-option span {
    color: #ef3340;
    font-size: 14px;
    font-weight: 600;
    overflow-wrap: anywhere;
}

/* Filename */
#imagePreview .image-filename {
    display: block;
    width: 100%;
    min-width: 0;
    margin-top: 10px;
    color: #111827;
    font-size: 14px;
    line-height: 1.5;
    text-align: center;
    overflow-wrap: anywhere;
    word-break: break-word;
}

/* Add image tile */
#imagePreview &gt; .image-add-tile {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    aspect-ratio: 1 / 1;
    height: auto;
    padding: 12px;
    border: 1px dashed #cbd5e1;
    border-radius: 12px;
    background: #fff;
    color: #475569;
    font-size: 16px;
    cursor: pointer;
}

#imagePreview .image-icon-wrap {
    position: relative;
    display: block;
    width: 80%;
    max-width: 100px;
    aspect-ratio: 88 / 70;
    height: auto;
}

#imagePreview .image-icon-wrap svg {
    display: block;
    width: 100%;
    height: 100%;
}

#imagePreview .image-plus {
    position: absolute;
    right: -7px;
    bottom: -7px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border: 2px solid #fff;
    border-radius: 50%;
    background: #2563eb;
    color: #fff;
    font-size: 24px;
    line-height: 1;
}

/* Tablet */
@media (max-width: 1100px) {
    #imagePreview {
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 24px 16px;
    }

    #imagePreview &gt; .image-item,
    #imagePreview &gt; .image-add-tile {
        max-width: none;
    }

    #imagePreview &gt; .image-item &gt; img {
        height: auto;
        aspect-ratio: 1 / 1;
    }
}

/* Mobile */
@media (max-width: 767px) {
    #imagePreview {
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 24px 12px;
    }

    #imagePreview &gt; .image-item &gt; img {
        height: auto;
        aspect-ratio: 1 / 1;
        padding: 5px;
    }

    #imagePreview .image-filename {
        font-size: 12px;
    }

    #imagePreview .remove-image {
        width: 26px;
        height: 26px;
        font-size: 19px;
    }
}

/* Small mobile */
@media (max-width: 420px) {
    #imagePreview {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 24px 14px;
    }
}




